query CartTransformRunInput {
  cart {
    lines {
      id
      quantity
      merchandise {
        __typename
        ... on ProductVariant {
          id
          title
          components: metafield(namespace: "$app:bundle", key: "components") {
            jsonValue
          }
        }
      }
    }
  }
}

// src/cart_transform_run.js
// Metafield da variante-kit: [{ "id": "gid://shopify/ProductVariant/1", "quantity": 2 }, ...]
export function cartTransformRun(input) {
  const operations = [];

  for (const line of input.cart.lines) {
    if (line.merchandise.__typename !== "ProductVariant") continue;

    const components = line.merchandise.components?.jsonValue;
    if (!Array.isArray(components) || components.length === 0) continue;

    operations.push({
      lineExpand: {
        cartLineId: line.id,
        title: line.merchandise.title,
        expandedCartItems: components.map((component) => ({
          merchandiseId: component.id,
          quantity: component.quantity, // por unidade do kit
        })),
      },
    });
  }

  return { operations };
}

// ajustando o preço do kit: preço fixo por unidade da linha expandida
{
  lineExpand: {
    cartLineId: line.id,
    expandedCartItems: components.map((c) => ({ merchandiseId: c.id, quantity: c.quantity })),
    price: {
      percentageDecrease: { value: 10 }, // 10% de desconto sobre a soma dos componentes
    },
  },
}

// linesMerge: junta linhas soltas numa só linha "kit" (ex.: camiseta + boné)
{
  linesMerge: {
    parentVariantId: "gid://shopify/ProductVariant/999",
    title: "Kit camiseta + boné",
    cartLines: [
      { cartLineId: camisa.id, quantity: 1 },
      { cartLineId: bone.id, quantity: 1 },
    ],
  },
}
